 "content": "def transform(grid):
    """Mark the missing end of a horizontal bar from its aligned counterpart."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    fg = next(x for x, _ in counts.most_common() if x != bg)
    out = [row[:] for row in grid]

    active = [r for r, row in enumerate(grid) if any(x != bg for x in row)]
    bands = []
    for r in active:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    upper, lower = bands[0], bands[1]
    offset = lower[0] - upper[0]
    # Paired rows share the same local position in the two patterned panels.
    for r in upper:
        s = r + offset
        if s not in lower:
            continue
        for target, source in ((r, s), (s, r)):
            # A missing suffix is completed only when the aligned row has a
            # solid foreground suffix at precisely those cells.
            c = w - 1
            while c >= 0 and grid[target][c] == bg:
                c -= 1
            start = c + 1
            if start < w and all(grid[source][x] == fg for x in range(start, w)):
                for x in range(start, w):
                    out[target][x] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
