 "content": "def transform(grid):
    """Extend the shortened horizontal color bar to match the other bar."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    freq = Counter(x for row in grid for x in row)
    bg = freq.most_common(1)[0][0]
    fg = next(x for x, _ in freq.most_common() if x != bg)
    out = [row[:] for row in grid]
    # Find horizontal runs of foreground in each row, compare bar lengths.
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, x in enumerate(row) if x == fg]
        if cols and cols == list(range(cols[0], cols[-1] + 1)):
            bars.append((r, cols[0], cols[-1]))
    # A truncated bar is identified by a row with a foreground interval and
    # a second longer interval at matching horizontal start. Extend only it.
    for i, (r, a, b) in enumerate(bars):
        for s, x, y in bars:
            if s != r and a == x and y > b:
                for c in range(b + 1, y + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 1
                break
    return out

