 "content": "def transform(grid):
    """Mark with 1 any missing terminal bar cells revealed by the matching row."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v, _ in counts.most_common() if v != bg)
    out = [row[:] for row in grid]

    # The examples contain two copies of a motif in separated horizontal bands.
    active_rows = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r != bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    upper, lower = bands[0], bands[1]
    offset = lower[0] - upper[0]
    for r in upper:
        s = r + offset
        if s not in lower:
            continue
        # If either aligned row has a blank suffix where the other has a
        # continuous foreground bar, mark precisely that suffix with 1.
        for target, source in ((r, s), (s, r)):
            c = w - 1
            while c >= 0 and grid[target][c] == bg:
                c -= 1
            start = c + 1
            if start < w and all(grid[source][x] == fg for x in range(start, w)):
                for x in range(start, w):
                    out[target][x] = 1
    return out

