 "content": "def transform(grid):
    """Fill the shorter repeated template wherever the matching object is longer."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    freq = Counter(v for row in grid for v in row)
    bg = freq.most_common(1)[0][0]
    fg = next(v for v, _ in freq.most_common() if v != bg)
    out = [row[:] for row in grid]

    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out
    a, b = bands[0], bands[1]
    # Both pattern copies have the same height and are aligned row-by-row.
    for r, s in zip(a, b):
        # Source provides foreground positions absent in the target row.
        for c in range(w):
            if grid[r][c] == bg and grid[s][c] == fg:
                out[r][c] = 1
            elif grid[s][c] == bg and grid[r][c] == fg:
                out[s][c] = 1
    return out

