 "content": "def transform(grid):
    """Highlight in 1 the right-hand pattern region of the upper motif panel."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    freq = Counter(x for row in grid for x in row)
    bg = freq.most_common(1)[0][0]
    fg = next(x for x, _ in freq.most_common() if x != bg)
    out = [row[:] for row in grid]
    active = [r for r, row in enumerate(grid) if any(x != bg for x in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out
    upper, lower = bands[0], bands[1]
    # Find the horizontal point where the lower motif panel ends; highlight
    # the foreground pattern of the upper panel beyond that shared extent.
    lower_right = max((c for r in lower for c, x in enumerate(grid[r]) if x == fg), default=-1)
    start = lower_right + 1
    if start < w:
        for r in upper:
            for c in range(start, w):
                if grid[r][c] == fg:
                    out[r][c] = 1
    return out

