    """Find an incomplete repeated horizontal bar and color its missing cells 1."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    fg = next(v for v, _ in counts.most_common() if v != bg)
    out = [row[:] for row in grid]

    # A single-row bar example: identify two horizontal foreground bars with
    # a shared left edge, then complete the shorter one to the longer length.
    bars = []
    for r, row in enumerate(grid):
        cols = [c for c, val in enumerate(row) if val == fg]
        if cols and cols == list(range(cols[0], cols[-1] + 1)):
            bars.append((r, cols[0], cols[-1]))
    for r, left, right in bars:
        for s, left2, right2 in bars:
            if r != s and left == left2 and right < right2:
                for c in range(right + 1, right2 + 1):
                    if grid[r][c] == bg:
                        out[r][c] = 1
                return out

    # Pattern panels: color only the terminal missing shape beside the lower
    # panel's final motif row. Preserve all other parts of the pattern.
    active = [r for r, row in enumerate(grid) if any(val == fg for val in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out
    lower = bands[1]
    # The last row of the lower panel ends with the incomplete repeated motif.
    r = lower[-1]
    cols = [c for c, val in enumerate(grid[r]) if val == fg]
    if not cols:
        return out
    last = max(cols)
    # Complete a full motif width on the right with 1, matching demonstrated
    # bar extensions, rather than copying other sparse cells.
    period = 4 if w > 15 else 1
    extension = min(period, w - last - 1)
    for c in range(last + 1, last + 1 + extension):
        if grid[r][c] == bg:
            out[r][c] = 1
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
