 "content": "def transform(grid):
    """Use the more complete of two aligned pattern panels as a template."""
    from collections import Counter
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = next(v for v, _ in counts.most_common() if v != background)
    out = [row[:] for row in grid]

    # Separate the two pattern panels by their all-background row gap.
    active_rows = [r for r, row in enumerate(grid) if any(v != background for v in row)]
    bands = []
    for r in active_rows:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)
    if len(bands) < 2:
        return out

    first, second = bands[0], bands[1]
    # The panel containing more foreground cells is the complete template;
    # mark the missing positions in the less complete copy.
    first_count = sum(v == foreground for r in first for v in grid[r])
    second_count = sum(v == foreground for r in second for v in grid[r])
    if first_count >= second_count:
        source, target = first, second
    else:
        source, target = second, first

    # Pair rows by their relative position within each repeated panel.
    for source_row, target_row in zip(source, target):
        for c in range(w):
            if grid[target_row][c] == background and grid[source_row][c] == foreground:
                out[target_row][c] = 1
    return out

