    active = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    bands = []
    for r in active:
        if not bands or r > bands[-1][-1] + 1:
            bands.append([r])
        else:
            bands[-1].append(r)

    # Repeated multi-row objects: compare corresponding rows in their bands.
    if len(bands) >= 2 and len(bands[0]) == len(bands[1]):
        a, b = bands[0], bands[1]
        end_a = max(c for r in a for c, v in enumerate(grid[r]) if v == fg)
        end_b = max(c for r in b for c, v in enumerate(grid[r]) if v == fg)
        if end_a != end_b:
